/**
 * Konfigurasi tipe data FID/FPD di portal.
 *
 * Satu komponen list (`FidFpd.vue`) & satu komponen detail (`FidFpdDetail.vue`)
 * dipakai bersama untuk semua tipe; pembeda hanya prop `type`. Map ini menautkan
 * tiap `type` ke: judul tampilan, nama route list & detail, serta apakah tipe
 * tersebut "FID-like" (menentukan tampil-tidaknya upload foto di Input Keterangan).
 *
 * `type` juga dikirim apa adanya ke backend (`juragan.api.portal.fid_fpd`) yang
 * memetakannya ke DocType sumber (lihat DOCTYPE_BY_TYPE di sisi Python).
 */
export const FID_FPD_TYPES = {
	fid: {
		title: 'FID',
		listRoute: 'Fid',
		detailRoute: 'FidDetail',
		isFid: true,
	},
	fpd: {
		title: 'FPD',
		listRoute: 'Fpd',
		detailRoute: 'FpdDetail',
		isFid: false,
	},
	fid_cutoff: {
		title: 'FID Cut Off Bulan Sebelumnya',
		listRoute: 'FidCutoff',
		detailRoute: 'FidCutoffDetail',
		isFid: true,
	},
	fpd_cutoff: {
		title: 'FPD Cut Off Bulan Sebelumnya',
		listRoute: 'FpdCutoff',
		detailRoute: 'FpdCutoffDetail',
		isFid: false,
	},
}

export function fidFpdConfig(type) {
	return FID_FPD_TYPES[type] || FID_FPD_TYPES.fid
}
